import numpy as np, tifffile
dark = tifffile.imread('/task/input/flatfield/dark.tif').astype(float)
f2 = tifffile.imread('/task/input/flatfield/flat_ch2.tif').astype(float)
def get(w):
    return (tifffile.imread(f'/task/input/images/{w}_ch2.tif').astype(float)-dark)/np.maximum(f2-dark,1e-6)
lows=['A10','B08','C05','E02','E07','F04','G07','H08']
imgs={w:get(w) for w in lows+['A01','A12']}
print('pairwise corr of corrected ch2:')
ws=list(imgs)
for i in range(len(ws)):
    for j in range(i+1,len(ws)):
        a,b=imgs[ws[i]].ravel(),imgs[ws[j]].ravel()
        r=np.corrcoef(a,b)[0,1]
        if r>0.5: print(f'{ws[i]}-{ws[j]}: {r:.3f}')
# also check raw file stats
for w in lows:
    raw=tifffile.imread(f'/task/input/images/{w}_ch2.tif')
    print(w, raw.min(), raw.max(), raw.mean())
